#!/usr/bin/env python3
"""Run C2 Unit06 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit06.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u06-p01':"""وفي مراجعة أخيرة طلبت المحللة من الأعضاء تفسير قرارين متشابهين اتخذا في سنتين مختلفتين. في السنة الأولى حُمِي بند الصيانة عند الخفض، وفي الثانية خُفض قليلًا لأن عقدًا آخر انتهى وسمح ببديل أرخص. لم تعتبر الفرق تقلبًا بالضرورة؛ بحثت عن القيد الذي تغير. أضاف المجلس إلى محاضره فقرة قصيرة تسجل البدائل المتاحة والسبب الذي جعل ترتيبها مختلفًا. بهذه الطريقة لا يتحول الاتساق إلى تكرار النتيجة نفسها مهما تغيرت الظروف، بل إلى تطبيق معلن للمعيار نفسه على قيود واحتياجات متغيرة.""",
'ar-c2-u06-p02':"""وفي مراجعة عمياء عرضت اللجنة أربع تعديلات سابقة على أعضاء جدد من دون إخبارهم بمن ربح كل مرة. طُلب منهم تصنيف القرار بحسب مقدار أثره في شروط المشاركة المستقبلية. تقاربت تقييماتهم أكثر من النقاش الأصلي لأن النتيجة الحزبية داخل المؤسسة الخيالية لم تعد ظاهرة. استخدمت اللجنة الفارق لتطوير قائمة خصائص: مدة الأثر، إمكان الرجوع، مقدار تغير فرص الحضور، وهل يمس القرار شروط تعديل القاعدة نفسها. لا تعطي القائمة جوابًا آليًا، لكنها تساعد على تحديد متى يحتاج الموضوع إلى إشعار أطول أو مسار مراجعة إضافي.""",
'ar-c2-u06-p03':"""وفي تمرين أخير طلبت اللجنة من مجموعتين صياغة محضر قصير يشرح سبب قبول عرض داخل حدود السلطة أو سبب طلب الرجوع. ظهرت فائدة التوثيق: أحد الفريقين اكتشف أن عرضه يعتمد على افتراض لم يذكر في التعليمات، فرفعه إلى الجهة الأصلية بدل إدخاله ضمن المساحة المرنة. لم يُعامل الرجوع بوصفه فشلًا في التفاوض؛ كان جزءًا من تصميم العلاقة. كما اتضح أن سرعة قناة الموافقة تحدد مقدار المرونة الواقعية: قاعدة جيدة على الورق تصبح جامدة إذا استغرق الرد وقتًا أطول من نافذة العرض.""",
'ar-c2-u06-p04':"""وفي مراجعة ثانية قارنت الهيئة بين عبء ظاهر وعبء تراكمي. قد تفقد مجموعة ساعة واحدة فقط في كل أسبوع، لكن إذا أجبرها النقل إلى موقع بعيد على دفع كلفة ثابتة أو فقدان متطوعين، يصبح أثر الأشهر أكبر من مجموع الساعات. لذلك طلبت تقدير الآثار المتكررة لا اللحظة الأولى فقط. كما اختبرت مدة تجريبية أقصر مع نقطة مراجعة مبكرة للمجموعات التي تظهر عليها آثار شديدة. لم يكن الهدف منح كل فئة مسارًا خاصًا، بل بناء آلية تلتقط عندما تختلف القدرة على التكيف فعلًا عن الافتراض الذي صمم عليه التغيير.""",
'ar-c2-u06-p05':"""وفي اختبار إضافي أزالت اللجنة الدرجة الجديدة مؤقتًا وأبقت الوقت والأدوات المخصصة للعمل المشترك. تحسن التعاون جزئيًا، ما أظهر أن نقص القدرة كان سببًا مستقلًا عن التقييم. ثم أعادت التقييم من دون تخصيص وقت، فتحسن جانب وتراجع آخر. أكدت المقارنة أن السلوك ينتج من حزمة شروط لا من رقم منفرد. لذلك سجلت الإدارة أثر كل تدخل على السرعة وجودة المشاركة وإعادة الاستخدام، وامتنعت عن إعلان نجاح النظام من مؤشر واحد. صار الإصلاح نفسه تجربة تكشف أي قيد كان أقوى في كل وحدة.""",
'ar-c2-u06-p06':"""وفي ختام المراجعة أعطت المحللة الطلاب حالة جديدة تجمع عقدًا قديمًا ومقياس أداء حديثًا وقاعدة طوارئ مؤقتة. اختلفوا في البداية على «من المسؤول»، ثم أعادتهم إلى الطبقات. تبين أن العقد يفسر جزءًا من قلة المرونة، وأن المقياس يدفع سلوكًا يزيد المشكلة، وأن الاستثناء المؤقت لم يعد يُراجع في موعده. لم يعد هناك سبب واحد يحمل القصة كلها. اقترح الطلاب إصلاحات مختلفة لكل حلقة وحددوا أي جهة تملكها ومتى يمكن تنفيذها. أظهر التمرين أن إعادة بناء المؤسسة تمنع البحث عن مذنب واحد عندما تكون النتيجة ناشئة من تراكم قرارات موزعة عبر الزمن.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
